// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
import { evolvePath } from "@remotion/paths";



export type MarketCalendarFlowProps = Record<string, any>;

// Static Data Points
const dailyCandles = [
  { x: 100, open: 600, close: 500, high: 460, low: 640, type: "up" },
  { x: 200, open: 500, close: 540, high: 480, low: 580, type: "down" },
  { x: 300, open: 540, close: 360, high: 320, low: 580, type: "up" },
  { x: 400, open: 360, close: 400, high: 340, low: 440, type: "down" },
  { x: 500, open: 400, close: 240, high: 200, low: 420, type: "up" },
  { x: 600, open: 240, close: 280, high: 220, low: 320, type: "down" },
  { x: 700, open: 280, close: 140, high: 100, low: 300, type: "up" },
];

const dailyMaPoints = [
  { x: 100, y: 560 }, { x: 200, y: 580 }, { x: 300, y: 480 },
  { x: 400, y: 420 }, { x: 500, y: 360 }, { x: 600, y: 280 }, { x: 700, y: 200 }
];
const dailyMaPath = "M " + dailyMaPoints.map((p) => `${p.x} ${p.y}`).join(" L ");

const volumeData = [50, 80, 40, 100, 60, 90, 70];

const quarterlyMonths = [
  [
    { x: 100, y: 250 }, { x: 200, y: 220 }, { x: 300, y: 260 },
    { x: 400, y: 180 }, { x: 500, y: 200 }, { x: 600, y: 120 }
  ],
  [
    { x: 100, y: 280 }, { x: 200, y: 240 }, { x: 300, y: 180 },
    { x: 400, y: 220 }, { x: 500, y: 120 }, { x: 600, y: 100 }
  ],
  [
    { x: 100, y: 240 }, { x: 200, y: 180 }, { x: 300, y: 200 },
    { x: 400, y: 120 }, { x: 500, y: 140 }, { x: 600, y: 60 }
  ]
];

const MarketCalendarFlow: React.FC<MarketCalendarFlowProps> = ({
  backgroundColor = "#000000",
  calendarColor = "#ffffff",
  accentColor = "#d93838",
  chartLineColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Global Timings
  const durationInFrames = durationInSeconds * fps;
  const outroFrame = durationInFrames - 20;

  const globalOutro = interpolate(frame, [outroFrame, outroFrame + 15], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const globalScale = 1 - globalOutro * 0.1;
  const globalOpacity = 1 - globalOutro;

  // Section 1: Daily Calendar Intro / Outro
  const dailyIntroSpring = spring({ frame: frame - 5, fps, config: { damping: 14 } });
  const dailyOutProgress = interpolate(frame, [65, 80], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  
  const dailyScale = dailyIntroSpring * (1 - dailyOutProgress * 0.2);
  const dailyOpacity = 1 - dailyOutProgress;
  const dailyTranslateY = dailyOutProgress * -50;

  // Section 1: Daily Market Visuals
  const maProgress = Math.max(0, Math.min(1, spring({ frame: frame - 15, fps, config: { damping: 20 }, durationInFrames: 45 })));
  const maEvolution = evolvePath(maProgress, dailyMaPath);

  const scannerProgress = spring({ frame: frame - 20, fps, config: { damping: 20 }, durationInFrames: 45 });
  const clampedScannerX = interpolate(Math.max(0, Math.min(1, scannerProgress)), [0, 1], [100, 700]);

  let scannerY = dailyMaPoints[0].y;
  for (let i = 0; i < dailyMaPoints.length - 1; i++) {
    if (clampedScannerX >= dailyMaPoints[i].x && clampedScannerX <= dailyMaPoints[i + 1].x) {
      const t = (clampedScannerX - dailyMaPoints[i].x) / (dailyMaPoints[i + 1].x - dailyMaPoints[i].x);
      scannerY = dailyMaPoints[i].y + t * (dailyMaPoints[i + 1].y - dailyMaPoints[i].y);
      break;
    }
  }

  // Section 2: Quarterly Calendars Base Timing
  const qStart = 70;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      <div style={{ width: "100%", height: "100%", position: "relative", transform: `scale(${globalScale})`, opacity: globalOpacity }}>
        
        {/* --- SECTION 1: DAILY CALENDAR --- */}
        <div style={{
          position: "absolute",
          left: width / 2 - 400,
          top: height / 2 - 450,
          width: 800,
          height: 900,
          transform: `scale(${dailyScale}) translateY(${dailyTranslateY}px)`,
          opacity: dailyOpacity,
          zIndex: 10,
        }}>
          <div style={{
            width: "100%",
            height: "100%",
            backgroundColor: calendarColor,
            borderRadius: 32,
            boxShadow: "0 30px 80px rgba(255,255,255,0.06)",
            position: "relative"
          }}>
            {/* Red Header */}
            <div style={{ height: 120, backgroundColor: accentColor, borderRadius: "32px 32px 0 0", width: "100%" }} />
            
            <svg width="800" height="780" style={{ position: "absolute", top: 120, left: 0 }}>
              {/* Grid Lines */}
              {Array.from({ length: 13 }).map((_, i) => (
                <line key={`dh-${i}`} x1={0} y1={i * 60} x2={800} y2={i * 60} stroke="#f3f4f6" strokeWidth={2} />
              ))}
              {Array.from({ length: 8 }).map((_, i) => (
                <line key={`dv-${i}`} x1={i * 100} y1={0} x2={i * 100} y2={780} stroke="#f3f4f6" strokeWidth={2} />
              ))}

              {/* Volume Bars */}
              {volumeData.map((vol, i) => {
                const volProgress = spring({ frame: frame - 30 - i * 3, fps, config: { damping: 14 } });
                const vHeight = Math.max(0, vol * volProgress);
                return (
                  <rect key={`vol-${i}`} x={dailyCandles[i].x - 16} y={780 - vHeight} width={32} height={vHeight} fill="#f3f4f6" />
                );
              })}

              {/* Chart Moving Average Line */}
              <path d={dailyMaPath} fill="none" stroke={chartLineColor} strokeWidth={8} opacity={0.1} strokeLinejoin="round" strokeDasharray={maEvolution.strokeDasharray} strokeDashoffset={maEvolution.strokeDashoffset} />
              <path d={dailyMaPath} fill="none" stroke={chartLineColor} strokeWidth={4} strokeLinejoin="round" strokeDasharray={maEvolution.strokeDasharray} strokeDashoffset={maEvolution.strokeDashoffset} />

              {/* Candlesticks */}
              {dailyCandles.map((c, i) => {
                const cProgress = spring({ frame: frame - 25 - i * 4, fps, config: { damping: 14 } });
                const currentHigh = interpolate(cProgress, [0, 1], [c.open, c.high]);
                const currentLow = interpolate(cProgress, [0, 1], [c.open, c.low]);
                const currentClose = interpolate(cProgress, [0, 1], [c.open, c.close]);
                const candleColor = c.type === "up" ? chartLineColor : accentColor;
                
                return (
                  <g key={`candle-${i}`}>
                    <line x1={c.x} y1={currentHigh - 120} x2={c.x} y2={currentLow - 120} stroke={candleColor} strokeWidth={4} />
                    <rect 
                      x={c.x - 12} 
                      y={Math.min(c.open, currentClose) - 120} 
                      width={24} 
                      height={Math.max(1, Math.abs(currentClose - c.open))} 
                      fill={candleColor} 
                      rx={4} 
                    />
                  </g>
                );
              })}

              {/* Scanner Line & Dot */}
              {frame > 20 && (
                <g>
                  <line x1={clampedScannerX} y1={0} x2={clampedScannerX} y2={780} stroke={accentColor} strokeWidth={8} opacity={0.15} />
                  <line x1={clampedScannerX} y1={0} x2={clampedScannerX} y2={780} stroke={accentColor} strokeWidth={2} strokeDasharray="6 6" />
                  <circle cx={clampedScannerX} cy={scannerY - 120} r={16} fill={accentColor} opacity={0.3} />
                  <circle cx={clampedScannerX} cy={scannerY - 120} r={6} fill={accentColor} />
                </g>
              )}
            </svg>
          </div>
          
          {/* Binder Rings */}
          <div style={{ position: "absolute", top: -30, left: 160, width: 40, height: 80, backgroundColor: "#e5e7eb", borderRadius: 20, border: "6px solid #fff", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }} />
          <div style={{ position: "absolute", top: -30, left: 600, width: 40, height: 80, backgroundColor: "#e5e7eb", borderRadius: 20, border: "6px solid #fff", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }} />
        </div>

        {/* --- SECTION 2: QUARTERLY CALENDARS --- */}
        <div style={{
          position: "absolute",
          left: width / 2 - 350,
          top: height / 2 - 690,
          width: 700,
          height: 1380,
          display: "flex",
          flexDirection: "column",
          gap: 60,
          zIndex: 5,
        }}>
          {quarterlyMonths.map((points, index) => {
            const mSpring = spring({ frame: frame - qStart - index * 5, fps, config: { damping: 16 } });
            const mOpacity = Math.min(1, Math.max(0, mSpring));
            const mScale = interpolate(mSpring, [0, 1], [0.9, 1]);
            const mTranslateY = interpolate(mSpring, [0, 1], [60, 0]);
            
            const mPath = "M " + points.map(p => `${p.x} ${p.y}`).join(" L ");
            const lineProgress = spring({ frame: frame - qStart - 15 - index * 5, fps, config: { damping: 20 }, durationInFrames: 40 });
            const mEvolution = evolvePath(Math.max(0, Math.min(1, lineProgress)), mPath);

            return (
              <div key={`month-${index}`} style={{
                width: 700, 
                height: 420, 
                backgroundColor: calendarColor, 
                borderRadius: 24, 
                position: "relative",
                transform: `scale(${mScale}) translateY(${mTranslateY}px)`, 
                opacity: mOpacity,
                boxShadow: "0 20px 60px rgba(255,255,255,0.05)"
              }}>
                {/* Header */}
                <div style={{ height: 80, backgroundColor: accentColor, borderRadius: "24px 24px 0 0" }} />
                
                {/* SVG Grid and Chart */}
                <svg width={700} height={340} style={{ position: "absolute", top: 80, left: 0 }}>
                  {Array.from({ length: 5 }).map((_, i) => (
                    <line key={`mh-${i}`} x1={0} y1={i * 68} x2={700} y2={i * 68} stroke="#f3f4f6" strokeWidth={2} />
                  ))}
                  {Array.from({ length: 7 }).map((_, i) => (
                    <line key={`mv-${i}`} x1={i * 100} y1={0} x2={i * 100} y2={340} stroke="#f3f4f6" strokeWidth={2} />
                  ))}
                  
                  {/* Glowing Track & Main Line */}
                  <path d={mPath} fill="none" stroke={chartLineColor} strokeWidth={8} opacity={0.1} strokeLinejoin="round" strokeLinecap="round" strokeDasharray={mEvolution.strokeDasharray} strokeDashoffset={mEvolution.strokeDashoffset} />
                  <path d={mPath} fill="none" stroke={chartLineColor} strokeWidth={4} strokeLinejoin="round" strokeLinecap="round" strokeDasharray={mEvolution.strokeDasharray} strokeDashoffset={mEvolution.strokeDashoffset} />
                  
                  {/* Data Dots */}
                  {points.map((p, pIndex) => {
                    const dotSpring = spring({ frame: frame - qStart - 20 - index * 5 - pIndex * 4, fps, config: { damping: 12 } });
                    return <circle key={`dot-${pIndex}`} cx={p.x} cy={p.y} r={6 * Math.max(0, dotSpring)} fill={accentColor} />
                  })}
                </svg>

                {/* Binder Rings */}
                <div style={{ position: "absolute", top: -20, left: 140, width: 30, height: 60, backgroundColor: "#e5e7eb", borderRadius: 15, border: "5px solid #fff", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }} />
                <div style={{ position: "absolute", top: -20, left: 530, width: 30, height: 60, backgroundColor: "#e5e7eb", borderRadius: 15, border: "5px solid #fff", boxShadow: "0 4px 10px rgba(0,0,0,0.1)" }} />
              </div>
            );
          })}
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default MarketCalendarFlow;